_ZHUANXUESHENG_TEXT = (
    "林小雅在開學典禮後的第一天，走進六年二班的教室。\n"
    "\n"
    "她穿著新的制服外套，袖子長了一點，被她捲起來。她站在門口，沒有馬上走進去。\n"
    "\n"
    "「大家早安，我是林小雅，請多指教。」她的聲音很小。\n"
    "\n"
    "沒有人回應。班上的吵鬧聲像水一樣，把她的話蓋了過去。有人笑，有人問她從哪一班來的，聲音大到全班都聽得見。\n"
    "\n"
    "她走到靠門的最後一排坐下。老師說，接下來的日子請大家多幫忙她。\n"
    "\n"
    "第一節課，她拿出新課本，發現上課的進度已經到第四課了。\n"
    "\n"
    "午餐時間，她一個人坐在教室角落。別人三三兩兩聚在一起，談昨天看的卡通。\n"
    "\n"
    "這樣過了三天，她開始不想開口說話。\n"
    "\n"
    "第四天早上，班上要辦氣球接力賽。分組的時候人數剛好多出一個人，大家你看我、我看你。\n"
    "\n"
    "「林小雅，你跟我們一隊。」體育股長阿玲突然說。\n"
    "\n"
    "「可是我不會跑。」\n"
    "\n"
    "「我們隊也不用跑最快，只要不掉隊就好。」\n"
    "\n"
    "比賽的時候，小雅一直落在最後。她知道自己拖累別人，一邊喘一邊想：乾脆不要跑了。\n"
    "\n"
    "「喂——」阿玲回頭停下來，「你停下來，我們隊就輸了。」\n"
    "\n"
    "小雅愣了一下，又開始跑。最後他們沒有拿到名次，但全班都在笑，有人拍她的肩膀。\n"
    "\n"
    "放學後，阿玲把一個信封塞給她。裡面是一張紙條，上面寫著：「妳是我認識的第四個新朋友。」後面畫了一個歪歪的符號。\n"
    "\n"
    "小雅笑了。她笑到有點想哭，因為她已經很久沒被人這樣寫在紙上了。\n"
    "\n"
    "從那天起，她慢慢學會了一件事：新的地方不會自己變熟悉，是要有人先把手伸過來。"
)

