_LIBRARY_TEXT = (
    "學校圖書館的角落有一個小木架，牌子上寫著「一週一本」。書裡都夾著一張薄薄的推薦卡，讀完要寫一句喜歡的話，"
    "再放回架上。這個規矩是三年前一位學姊訂的，一直維持得很好。\n"
    "\n"
    "只有一張卡是空白的。\n"
    "\n"
    "那一週的書是《走過的路》，一個星期裡被借走又放回來不下十次，裡面的推薦卡卻連續三個星期都是空白。"
    "管理員把卡抽出來對著燈光看，卡上乾乾淨淨，一個字都沒有。\n"
    "\n"
    "「大概是真的忘了寫吧。」她說。\n"
    "\n"
    "圖書股長小千覺得不對勁。書被借得這麼勤，沒有人會讀完一句話都不寫。她把卡湊近聞了聞，再用手機的燈斜斜照過去。\n"
    "\n"
    "卡面是白的，紙卻不光滑。橡皮擦過的地方會變得粗糙，寫過又擦掉的字會在斜光下留下淡淡的影子。她看見了三個字的殘影，"
    "歪歪斜斜：不、要、寫。\n"
    "\n"
    "小千把卡放回書裡，沒有換書，也沒有去問誰。接下來三天，她每天放學都留在圖書館，什麼也不做，只是看著那個木架。\n"
    "\n"
    "第四天放學，六年二班的阿信來借書。他是那本書借得最勤的人，個子小，總把書抱在胸前。他把書抽出來，翻到最後一頁，"
    "看見空白的卡，愣了兩秒，然後從鉛筆盒裡拿出橡皮，擦了很久。\n"
    "\n"
    "「你每天都寫，又每天擦掉。」小千說。\n"
    "\n"
    "阿信的耳朵紅了。他說自己寫得很慢，一句話要重寫好幾次，寫壞了就擦，擦到最後卡片就白了。他怕別人看到他寫得很醜。\n"
    "\n"
    "小千沒有叫他重寫。她拿出另一張卡，在中間畫了一個小方框，說：「那你填一個數字就好。第幾頁最喜歡？」\n"
    "\n"
    "阿信想了很久，寫下四十三。\n"
    "\n"
    "「為什麼是那一頁？」\n"
    "\n"
    "「因為那一頁在講他的爸爸。」\n"
    "\n"
    "那一週，管理員照例翻開書裡的推薦卡。這一次，卡上不再是一片空白。"
)

