_TAPE_TEXT = (
    "美術課要交紙模型，老師說明膠帶可以用。教室後面的公用膠帶架上，卻只剩三捲空芯。\n"
    "\n"
    "班上用的膠帶是跟隔壁班借來的。記錄借用品的是阿美，她的簿子上寫著：膠帶，上學期一共借出七捲，實際用掉不到一捲。\n"
    "\n"
    "「那剩下的六捲去了哪裡？」有一天中午，小光聽到別人這樣問。\n"
    "\n"
    "那天下午，小光把自己的鉛筆盒拿出來擦。盒蓋上排著整整三十幾小條彩色膠帶，一條一條，顏色都不一樣，"
    "像一條小小的彩虹。\n"
    "\n"
    "阿美看了很久，問：「這些是哪來的？」\n"
    "\n"
    "「我自己的。」小光說。\n"
    "\n"
    "那是假的。那些膠帶的切口都和公用膠帶一樣平整，而且每一條都從最前面撕下來。公用膠帶捲到最後三十公分會變得又厚又難撕，"
    "撕下來的一截兩邊會翹起來，斷口毛毛的，不會這麼齊。\n"
    "\n"
    "放學後，阿美把小光單獨留下來。\n"
    "\n"
    "「為什麼要拿？」\n"
    "\n"
    "小光低著頭說，他媽媽在早餐店工作，早上五點就出門。他一個星期有三個晚上是吃泡麵的。零用錢都變成了便當，"
    "膠帶是他最捨不得買、卻最想買的東西。\n"
    "\n"
    "「可是學校有。」\n"
    "\n"
    "「可是學校的是學校的。」\n"
    "\n"
    "阿美沒有罵他。第二天，她帶了一個空的奶粉罐子到班上，說：「誰家有多餘的膠帶，丟進來。」\n"
    "\n"
    "那個星期五，罐子裡裝了十九捲。有人丟了一整捲新的，有人丟了用剩的半捲。阿美在罐子外面貼了一張紙條："
    "公用膠帶，用完請撕整條。\n"
    "\n"
    "小光鉛筆盒上那三十幾條膠帶，一個星期後都不見了。他自己一條一條撕下來，摺成一個小方塊，放進垃圾桶。\n"
    "\n"
    "「下次我買。」他說。\n"
    "\n"
    "「不用。」阿美說，「罐子裡有。」"
)

