    "\n"
    "我發現這件事，是因為我每天也在同樣的時間坐在陽台。"
    "起初牠看到我會立刻跳走。過了一個月，牠只是抬頭看我一眼，繼續坐著。\n"
    "\n"
    "有一天，我試著把一小塊魚放在我們之間的矮牆上。"
    "牠沒有動。隔天，那塊魚不見了。我又放了一塊。\n"
    "\n"
    "這樣過了三個月。有一天傍晚，牠走過矮牆，"
    "在我的陽台上坐了下來。牠把尾巴收好，面朝夕陽，離我不到一公尺。\n"
