_BASKETBALL_TEXT = (
    "我們班的籃球破了。那是一顆橘色的球，"
    "上面的紋路早就磨平，還有一道補過的痕跡。\n"
    "\n"
    "那顆球是上一屆學長留下來的。學長畢業前說："
    "「這顆球陪我們打了三年球賽，你們要繼續用。」\n"
    "\n"
    "破了以後，班上分成兩派。一派說要買新的，"
    "一派說要拿去補。\n"
    "\n"
    "最後我們決定拿去給修鞋的阿伯補。阿伯看了看，說："
    "「這顆球補過三次了，再補一次，就只能當練習球。」\n"
    "\n"
    "我們說好。\n"
    "\n"
    "新的球買了，放在體育股的櫃子裡；"
    "舊的球繼續在放學後被我們拿出來打。"
    "後來發現，其實大家都比較喜歡打那顆舊的。"
)

