# ------------------------------------------------------------

_GRAD_TRIP_TEXT = (
    "畢業旅行前一天晚上，我把行李箱打開，又關上，再打開。"
    "媽媽說：「你已經檢查五次了。」\n"
    "\n"
    "我不是緊張行李。我是緊張，明天要和這些同學一起出去。"
    "我們同班兩年，有些人我還沒說過幾句話。\n"
    "\n"
    "那天晚上，我在班上的群組裡看到有人問："
    "「有沒有人要一起坐遊覽車最後一排？」\n"
    "\n"
    "我打了「我」，又刪掉。再打一次「我」，又刪掉。\n"
    "\n"
    "最後我按下送出。三秒鐘後，另一個人回：「我也是最後一排。」\n"
    "\n"
    "隔天早上，我提著行李箱上車。走到最後一排，"
    "那個人已經坐在靠窗的位置，旁邊空著。\n"
    "\n"
    "我把行李放上去，坐下來。他看了我一眼，"
    "說：「你也是最後一排的。」\n"
    "\n"
    "我說：「對。」\n"
    "\n"
    "遊覽車開動的時候，我們都沒有再說話。"
)

